    if sides[0] <= 0 or sides[0] + sides[1] <= sides[2]:
        raise TriangleError('illegal triangle')
    if a == b == c:
        return 'equilateral'
    if a == b or b == c or a == c:
        return 'isosceles'
    return 'scalene'

